#!/usr/bin/env julia

# convert_uniform_bridge_certificate_parte3.jl
#
# Lê um JSON no formato do certificado uniforme e gera um arquivo Lean
# "data-only" (sem axiomas/sorry) com:
#   - m_min (ℕ)
#   - logm_min.lo/hi (ℚ)
#   - tabelas por x ∈ Fin 9: omega_lo/omega_hi/u_lo/u_hi (ℚ)
#
# Uso:
#   julia convert_uniform_bridge_certificate_parte3.jl \
#       certs/uniform_bridge_certificate_parte3.json \
#       RoughBlocks/External/Certs/uniform_bridge_certificate_parte3.lean
#
# Dependências: JSON3.jl

using JSON3
using Printf

# parse seguro para BigInt (aceita String ou SubString)
parse_bigint(s) = parse(BigInt, String(s))

function rat_from_decimal_str(s::AbstractString)
    str = strip(String(s))
    if isempty(str)
        error("string vazia ao converter para racional")
    end
    sign = 1
    if startswith(str, '+')
        str = str[2:end]
    elseif startswith(str, '-')
        sign = -1
        str = str[2:end]
    end
    # apenas dígitos e ponto
    if occursin(r"[^0-9.]", str)
        error("caracter inválido em decimal: $s")
    end
    if count(==('.'), str) > 1
        error("mais de um ponto decimal: $s")
    end
    if '.' ∈ str
        parts = split(str, '.'; limit=2)
        intpart = isempty(parts[1]) ? "0" : parts[1]
        fracpart = length(parts) == 2 ? parts[2] : "0"
        num = parse_bigint(intpart)
        den = big(1)
        if !isempty(fracpart)
            den = big(10)^length(fracpart)     # BigInt ^ Int → BigInt
            num = num * den + parse_bigint(fracpart)
        end
        num *= sign
        g = gcd(abs(num), den)
        return (num ÷ g, den ÷ g)
    else
        return (sign * parse_bigint(str), big(1))
    end
end

function lean_rat(num::BigInt, den::BigInt)
    if den == 1
        return string("(", num, " : ℚ)")
    else
        return string("(", num, " : ℚ) / (", den, " : ℚ)")
    end
end

lean_rat_from_str(s) = begin
    num, den = rat_from_decimal_str(s)
    lean_rat(num, den)
end

function emit_fin9_match(name::String, qs::Vector{String})
    if length(qs) != 9
        error("esperava 9 itens para Fin 9, recebido $(length(qs))")
    end
    io = IOBuffer()
    println(io, "def $name : Fin 9 → ℚ")
    for i in 0:8
        qi = qs[i+1]
        println(io, "| ⟨$i, _⟩ => $qi")
    end
    String(take!(io))
end

if length(ARGS) < 2
    println(stderr, "Uso: julia convert_uniform_bridge_certificate_parte3.jl INPUT.json OUTPUT.lean")
    exit(1)
end
inpath  = ARGS[1]
outpath = ARGS[2]

json = JSON3.read(read(inpath, String))

domain = json["domain"]
m_min_str = String(domain["m_min"])
m_min = parse(Int, m_min_str)

logm_min_interval = domain["logm_min_interval"]
logm_lo = lean_rat_from_str(String(logm_min_interval["lo"]))
logm_hi = lean_rat_from_str(String(logm_min_interval["hi"]))

by_x = json["by_x"]
if length(by_x) != 9
    error("by_x deve ter 9 entradas (0..8), tem $(length(by_x))")
end

omega_lo = Vector{String}(undef, 9)
omega_hi = Vector{String}(undef, 9)
u_lo     = Vector{String}(undef, 9)
u_hi     = Vector{String}(undef, 9)

for entry in by_x
    x      = Int(entry["x"])
    w_rng  = entry["omega_range"]
    u_rng  = entry["u_range"]
    omega_lo[x+1] = lean_rat_from_str(String(w_rng["lo"]))
    omega_hi[x+1] = lean_rat_from_str(String(w_rng["hi"]))
    u_lo[x+1]     = lean_rat_from_str(String(u_rng["lo"]))
    u_hi[x+1]     = lean_rat_from_str(String(u_rng["hi"]))
end

io = IOBuffer()

println(io, "/-")
println(io, "This file was autogenerated from: $inpath")
println(io, "Do not edit by hand. Re-generate via convert_uniform_bridge_certificate_parte3.jl.")
println(io, "-/")
println(io)
println(io, "import Mathlib")
println(io, "import RoughBlocks.Heavy.Interface")
println(io, "import RoughBlocks.External.Certs.UniformLB18794Bridge")
println(io)
println(io, "namespace RoughBlocks.External.Certs")
println(io, "noncomputable section")
println(io, "open Classical Real")
println(io, "open RoughBlocks.Heavy")
println(io, "open RoughBlocks.External.Certs.UniformLB18794Bridge")
println(io)
println(io, "/-- Minimum m guaranteed by the uniform bridge certificate (from JSON). -/")
println(io, "def m_min_from_cert : ℕ := $m_min")
println(io)
println(io, "/-- A closed rational interval enclosing log(m_min). -/")
println(io, "def logm_min_lo_q : ℚ := $logm_lo")
println(io, "def logm_min_hi_q : ℚ := $logm_hi")
println(io)
println(io, "/-- Per-block lower bounds for ω(u) from the certificate (as rationals). -/")
println(io, emit_fin9_match("omega_lo_q_from_cert", omega_lo))
println(io)
println(io, "/-- Per-block upper bounds for ω(u) from the certificate (as rationals). -/")
println(io, emit_fin9_match("omega_hi_q_from_cert", omega_hi))
println(io)
println(io, "/-- Per-block lower/upper bounds for u from the certificate (as rationals). -/")
println(io, emit_fin9_match("u_lo_q_from_cert", u_lo))
println(io)
println(io, emit_fin9_match("u_hi_q_from_cert", u_hi))
println(io)
println(io, "/-- Real-valued views (coercions). -/")
println(io, "def omega_lo_from_cert (x : Fin 9) : ℝ := (omega_lo_q_from_cert x : ℝ)")
println(io, "def omega_hi_from_cert (x : Fin 9) : ℝ := (omega_hi_q_from_cert x : ℝ)")
println(io, "def u_lo_from_cert     (x : Fin 9) : ℝ := (u_lo_q_from_cert x : ℝ)")
println(io, "def u_hi_from_cert     (x : Fin 9) : ℝ := (u_hi_q_from_cert x : ℝ)")
println(io)
println(io, "/- Data only; use these in your Part 4 proofs. -/")
println(io)
println(io, "end")
println(io, "end RoughBlocks.External.Certs")
println(io)

open(outpath, "w") do f
    write(f, String(take!(io)))
end

println("OK: wrote Lean data module to $outpath")